#!/usr/bin/env node
/*
 * Concatenates the classic shell scripts listed in js/bootstrap/load-order.json
 * into js/avian-game.bundle.js. Pure Node stdlib — no dependencies.
 *
 * Usage:
 *   node scripts/build-bundle.js          # one-shot build
 *   node scripts/build-bundle.js --watch  # rebuild on source change
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const MANIFEST = path.join(ROOT, 'js', 'bootstrap', 'load-order.json');
const OUTPUT = path.join(ROOT, 'js', 'avian-game.bundle.js');

function readManifest() {
  const raw = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  const list = raw.gameShellScripts || raw;
  if (!Array.isArray(list)) {
    throw new Error('load-order.json: gameShellScripts must be an array');
  }
  return list;
}

function buildOnce() {
  const start = Date.now();
  const files = readManifest();
  const header =
    '/* Avian Ascent — generated by scripts/build-bundle.js. Do not edit by hand.\n' +
    ' * Source order: js/bootstrap/load-order.json\n' +
    ' */\n';
  const parts = [header];
  let totalBytes = 0;
  for (const rel of files) {
    const full = path.join(ROOT, rel);
    if (!fs.existsSync(full)) {
      throw new Error(`Missing manifest entry: ${rel}`);
    }
    const src = fs.readFileSync(full, 'utf8');
    totalBytes += src.length;
    parts.push(`\n;/* === ${rel.replace(/\\/g, '/')} === */\n`);
    parts.push(src);
  }
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, parts.join(''), 'utf8');
  const ms = Date.now() - start;
  console.log(
    `[bundle] wrote js/avian-game.bundle.js (${files.length} files, ${(totalBytes / 1024).toFixed(1)} KiB source) in ${ms} ms`,
  );
  return files;
}

function watch() {
  let pending = false;
  let timer = null;
  let watchedFiles = [];
  const watchers = [];

  function rebuild() {
    if (pending) return;
    pending = true;
    clearTimeout(timer);
    timer = setTimeout(() => {
      pending = false;
      try {
        const next = buildOnce();
        const nextSet = new Set(next.map((p) => p.replace(/\\/g, '/')));
        const prevSet = new Set(watchedFiles);
        const changed =
          next.length !== watchedFiles.length ||
          [...nextSet].some((f) => !prevSet.has(f));
        if (changed) attachWatchers(next);
      } catch (err) {
        console.error('[bundle] build failed:', err.message);
      }
    }, 80);
  }

  function attachWatchers(files) {
    while (watchers.length) {
      try {
        watchers.pop().close();
      } catch {
        /* noop */
      }
    }
    watchedFiles = files.map((p) => p.replace(/\\/g, '/'));
    for (const rel of files) {
      const full = path.join(ROOT, rel);
      try {
        const w = fs.watch(full, { persistent: true }, () => rebuild());
        watchers.push(w);
      } catch (err) {
        console.warn(`[bundle] cannot watch ${rel}: ${err.message}`);
      }
    }
    try {
      const w = fs.watch(MANIFEST, { persistent: true }, () => rebuild());
      watchers.push(w);
    } catch (err) {
      console.warn(`[bundle] cannot watch load-order.json: ${err.message}`);
    }
  }

  const initial = buildOnce();
  attachWatchers(initial);
  console.log(`[bundle] watching ${initial.length} files for changes…`);
}

const args = process.argv.slice(2);
if (args.includes('--watch') || args.includes('-w')) {
  watch();
} else {
  buildOnce();
}
